"""Live parameter edits for the canonical original-span input bridge."""
import math
import struct
import bpy
import bmesh


def input_property(controller, name):
    modifier=next(m for m in controller.modifiers if m.type=='NODES')
    socket=next(s for s in modifier.node_group.interface.items_tree
        if s.item_type=='SOCKET' and s.in_out=='INPUT' and s.name==name)
    return getattr(modifier.properties.inputs,socket.identifier)


def sources(controller):
    collection=input_property(controller,'Source Objects').value
    return ((controller,) if len(controller.data.edges) else ()) + tuple(collection.all_objects if collection else ())


def section_object(controller, section_id):
    matches=[]
    for obj in sources(controller):
        if obj.mode=='EDIT':
            bm=bmesh.from_edit_mesh(obj.data);ids=bm.edges.layers.int.get('st_section_id')
            found=ids is not None and any(e[ids]==section_id for e in bm.edges)
        else:
            ids=obj.data.attributes.get('st_section_id')
            found=ids is not None and any(v.value==section_id for v in ids.data)
        if found:matches.append(obj)
    if len(matches)!=1:raise ValueError('Section must have one editable source owner')
    return matches[0]


def parameters(controller, section_id):
    obj=section_object(controller,section_id)
    if obj.mode=='EDIT':
        bm=bmesh.from_edit_mesh(obj.data);ids=bm.edges.layers.int.get('st_section_id')
        edge=next(e for e in bm.edges if e[ids]==section_id)
        return tuple(edge[bm.edges.layers.float.get(k)] for k in ('st_width','st_offset'))
    at=next(i for i,v in enumerate(obj.data.attributes['st_section_id'].data) if v.value==section_id)
    return tuple(obj.data.attributes[k].data[at].value for k in ('st_width','st_offset'))


def set_parameters(controller, section_id, *, width=None, offset=None, interpolation=None):
    if interpolation not in (None,3):
        raise ValueError('The original-span candidate currently supports Smooth interpolation only')
    values={}
    for key,value in (('st_width',width),('st_offset',offset)):
        if value is None:continue
        try:value=struct.unpack('f',struct.pack('f',float(value)))[0]
        except (ValueError,TypeError,OverflowError):raise ValueError('Section parameters must fit finite mesh floats') from None
        if not math.isfinite(value) or (key=='st_width' and value<=0):
            raise ValueError('Section width must be positive and all parameters finite')
        values[key]=value
    obj=section_object(controller,section_id)
    edit=obj.mode=='EDIT';bm=bmesh.from_edit_mesh(obj.data) if edit else bmesh.new()
    if not edit:bm.from_mesh(obj.data)
    try:
        ids=bm.edges.layers.int.get('st_section_id')
        modes=bm.edges.layers.int.get('st_interpolation')
        layers={k:bm.edges.layers.float.get(k) for k in values}
        if ids is None or any(v is None for v in layers.values()) or (interpolation is not None and modes is None):
            raise ValueError('Source Section parameter attributes are missing')
        for edge in bm.edges:
            if edge[ids]==section_id:
                for key,value in values.items():edge[layers[key]]=value
                if interpolation is not None:edge[modes]=interpolation
        if edit:bmesh.update_edit_mesh(obj.data,loop_triangles=False,destructive=False)
        else:bm.to_mesh(obj.data);obj.data.update()
        obj.update_tag()
    finally:
        if not edit:bm.free()
    return section_id


def select_section_joint_copies(controller, context):
    """Expand Edit Mode selection through the saved native source binding.

    No coordinates, topology, attributes or GN graphs are changed. If a paired
    Section lives in another visible source object, include it in multi-object
    Edit Mode. This is an explicit command, with no update handler or timer.
    """
    from .source_joint_selection import expand_joint_selection
    if context.mode != 'EDIT_MESH':
        raise ValueError('Select a source vertex in Edit Mode first')
    objects = tuple(dict.fromkeys(sources(controller)))
    if any(obj.type != 'MESH' for obj in objects):
        raise ValueError('Street sources must be meshes')
    editing = tuple(context.objects_in_mode)
    if not set(editing) <= set(objects):
        raise ValueError('Edit only sources belonging to this street network')
    if len({o.data.as_pointer() for o in objects}) != len(objects):
        raise ValueError('Source objects must not share an editable mesh')
    binding = input_property(controller, 'Source Binding').value
    if binding is None or binding.type != 'MESH':
        raise ValueError('The original Section source binding is missing')
    fields = []
    for key in ('_pv_vertex', '_pv_alias'):
        attr = binding.data.attributes.get(key)
        if attr is None or attr.domain != 'POINT' or attr.data_type != 'INT':
            raise ValueError('The original Section joint binding is missing')
        fields.append([v.value for v in attr.data])
    count = input_property(controller, 'Source Vertex Count').value
    targets, selected, roles, edges = {}, set(), {}, {}
    for obj in objects:
        if obj.type != 'MESH':
            raise ValueError('Street sources must be meshes')
        if obj.mode == 'EDIT':
            bm = bmesh.from_edit_mesh(obj.data)
            bm.verts.ensure_lookup_table()
            ids = bm.verts.layers.int.get('st_live_vertex_index')
            endpoint = bm.verts.layers.int.get('st_endpoint_role')
            edge_ids = bm.edges.layers.int.get('st_live_edge_index')
            section_ids = bm.edges.layers.int.get('st_section_id')
            if any(layer is None for layer in (ids, endpoint, edge_ids, section_ids)):
                raise ValueError('Source topology lookup is missing')
            rows = [(v[ids], i, v.select) for i, v in enumerate(bm.verts)]
            role_rows = [(v[ids], v[endpoint]) for v in bm.verts]
            edge_rows = [(e[edge_ids], (e.verts[0][ids], e.verts[1][ids]), e[section_ids]) for e in bm.edges]
        else:
            attrs = {}
            for key, domain in (('st_live_vertex_index', 'POINT'), ('st_endpoint_role', 'POINT'),
                                ('st_live_edge_index', 'EDGE'), ('st_section_id', 'EDGE')):
                attr = obj.data.attributes.get(key)
                if attr is None or attr.domain != domain or attr.data_type != 'INT':
                    raise ValueError('Source topology lookup is missing')
                attrs[key] = attr
            ids = attrs['st_live_vertex_index']
            rows = [(v.value, i, False) for i, v in enumerate(ids.data)]
            role_rows = [(v.value, attrs['st_endpoint_role'].data[i].value) for i, v in enumerate(ids.data)]
            edge_rows = [(attrs['st_live_edge_index'].data[e.index].value,
                          tuple(ids.data[v].value for v in e.vertices), attrs['st_section_id'].data[e.index].value)
                         for e in obj.data.edges]
        for live, index, is_selected in rows:
            if live in targets:
                raise ValueError('Source vertex lookup is duplicated; rebuild the topology binding')
            targets[live] = (obj, index)
            if is_selected:
                selected.add(live)
        roles.update(role_rows)
        for live, ends, section in edge_rows:
            if live in edges:
                raise ValueError('Source edge lookup is duplicated; rebuild the topology binding')
            edges[live] = (set(ends), section)
    if set(targets) != set(range(count)):
        raise ValueError('Source topology changed; rebuild the topology binding')
    expanded = expand_joint_selection(zip(*fields), selected, count)
    def bound(key, domain):
        attr = binding.data.attributes.get(key)
        if attr is None or attr.domain != domain or attr.data_type != 'INT':
            raise ValueError('The original Section topology binding is missing')
        return [v.value for v in attr.data]
    for vertex, alias, role in zip(*fields, bound('_pv_role', 'POINT')):
        if roles[vertex] != role or (alias >= 0 and roles[alias] != 1):
            raise ValueError('Source endpoint roles changed; rebuild the topology binding')
    edge_fields = [bound(key, 'EDGE') for key in ('_pv_edge', '_pv_first', '_pv_last', 'st_section_id')]
    if len(set(edge_fields[0])) != len(edge_fields[0]) or set(edges) != set(edge_fields[0]):
        raise ValueError('Source edge topology changed; rebuild the topology binding')
    for index, first, last, section in zip(*edge_fields):
        if edges[index] != ({first, last}, section):
            raise ValueError('Source Section connectivity changed; rebuild the topology binding')
    if not selected:
        raise ValueError('Select at least one source vertex')
    added = expanded - selected
    needed = {targets[i][0] for i in added} - set(editing)
    for obj in needed:
        if obj.library is not None or obj.data.library is not None or obj.hide_select or not obj.visible_get():
            raise ValueError('Make the paired Section source visible and editable first: '+obj.name)
    active = context.view_layer.objects.active
    # Validate the complete lookup and every target before changing selection.
    # New objects have their dormant mesh selection cleared so an unrelated
    # previously selected control does not accidentally join the next move.
    if needed:
        bpy.ops.object.mode_set(mode='OBJECT')
        for obj in context.selected_objects:
            obj.select_set(False)
        for obj in needed:
            for element in (*obj.data.vertices, *obj.data.edges, *obj.data.polygons):
                element.select = False
        for obj in set(editing) | needed:
            obj.select_set(True)
        context.view_layer.objects.active = active
        bpy.ops.object.mode_set(mode='EDIT')
    context.tool_settings.mesh_select_mode = (True, False, False)
    by_object = {}
    for live in expanded:
        obj, index = targets[live]
        by_object.setdefault(obj, []).append(index)
    for obj, indices in by_object.items():
        bm = bmesh.from_edit_mesh(obj.data)
        bm.verts.ensure_lookup_table()
        for index in indices:
            bm.verts[index].select_set(True)
        bm.select_flush_mode()
        bmesh.update_edit_mesh(obj.data, loop_triangles=False, destructive=False)
    return len(added)


def draw(layout, controller):
    layout.label(text='Original-span streets (preview)')
    modifier=next(m for m in controller.modifiers if m.type=='NODES')
    inputs={s.name for s in modifier.node_group.interface.items_tree
            if s.item_type=='SOCKET' and s.in_out=='INPUT'}
    for name in ('Mesh Resolution','Cell Size','Height Exaggeration','Pavement','Grass'):
        # Earlier saved preview libraries predate the separator material input.
        if name=='Grass' and name not in inputs:continue
        layout.prop(input_property(controller,name),'value',text=name)
    layout.label(text='Move source vertices in Edit Mode.')
    row = layout.row()
    row.enabled = bpy.context.mode == 'EDIT_MESH'
    row.operator('streets.select_section_joint_copies')
    layout.label(text='At Section joins, select both copies before moving.')
    layout.label(text='Smooth interpolation only.')
    layout.label(text='Topology commands are not yet supported.')
